# owner: platform
"""Find the stretches of opening hours nobody covers."""

from hourglass.models import Span
from hourglass.merging import merge_spans

def _clock(minute: int) -> str:
    return f"{minute // 60:02d}:{minute % 60:02d}"

def _check(worked, opening: Span) -> None:
    for span in worked:
        if span.start < opening.start:
            raise ValueError(f"outside opening: {span}")
        if span.end > opening.end:
            raise ValueError(f"outside opening: {span}")

def _label(start: int, end: int) -> str:
    text = f"{_clock(start)}-{_clock(end)}"
    return f"gap {text} ({end - start} min)"

def _labels(begins, ends) -> list:
    labels = []
    for start, stop in zip(begins, ends):
        if start < stop:
            labels.append(_label(start, stop))
    return labels

def find_gaps(worked, opening: Span) -> list:
    """One label per uncovered stretch of opening hours."""
    _check(worked, opening)
    merged = merge_spans(worked)
    begins = [opening.start] + [item.end for item in merged]
    ends = [item.start for item in merged] + [opening.end]
    return _labels(begins, ends)
